/* Signed 32-bit authoring values are retained as low/high 16-bit words. */
typedef struct LoomGeneratedStableId {
    loom_u8 bytes[16];
} LoomGeneratedStableId;

typedef struct LoomGeneratedAssetRecord {
    LoomGeneratedStableId id;
    loom_u16 first_item;
    loom_u16 item_count;
    loom_u16 first_output;
    loom_u16 output_count;
    loom_u16 kind;
} LoomGeneratedAssetRecord;

typedef struct LoomGeneratedAssetItemRecord {
    LoomGeneratedStableId id;
    loom_u16 asset;
    loom_u16 kind;
} LoomGeneratedAssetItemRecord;

typedef struct LoomGeneratedAssetOutputRecord {
    LoomGeneratedStableId owner;
    loom_u8 sha256[32];
    loom_u16 byte_length_words[4];
    loom_u16 asset;
    loom_u16 role;
} LoomGeneratedAssetOutputRecord;

typedef struct LoomGeneratedSceneRecord {
    LoomGeneratedStableId id;
    loom_u16 width_metatiles;
    loom_u16 height_metatiles;
    loom_u16 first_layer;
    loom_u16 layer_count;
    loom_u16 first_entity;
    loom_u16 entity_count;
    loom_u16 profile;
} LoomGeneratedSceneRecord;

typedef struct LoomGeneratedLayerRecord {
    LoomGeneratedStableId id;
    loom_u16 scene;
    loom_u16 order;
    loom_u16 kind;
    loom_u16 visible;
    loom_u16 first_cell;
    loom_u16 cell_count;
} LoomGeneratedLayerRecord;

typedef struct LoomGeneratedTileCellRecord {
    LoomGeneratedStableId metatile;
    loom_u16 source_index_words[2];
    loom_u16 x;
    loom_u16 y;
    loom_u16 flags;
} LoomGeneratedTileCellRecord;

typedef struct LoomGeneratedCollisionCellRecord {
    loom_u16 source_index_words[2];
    loom_u16 x;
    loom_u16 y;
    loom_u16 material;
} LoomGeneratedCollisionCellRecord;

typedef struct LoomGeneratedEntityRecord {
    LoomGeneratedStableId id;
    loom_u16 position_words[4];
    loom_u16 scene;
    loom_u16 order;
    loom_u16 first_component;
    loom_u16 component_count;
} LoomGeneratedEntityRecord;

/* Component data words are kind-specific and documented in generated-output.md. */
typedef struct LoomGeneratedComponentRecord {
    LoomGeneratedStableId id;
    LoomGeneratedStableId reference;
    loom_u16 data[8];
    loom_u16 entity;
    loom_u16 order;
    loom_u16 kind;
    loom_u16 flags;
} LoomGeneratedComponentRecord;

typedef struct LoomGeneratedWorldRecord {
    LoomGeneratedStableId id;
    LoomGeneratedStableId initial_spawn;
    loom_u16 first_room;
    loom_u16 room_count;
    loom_u16 first_connection;
    loom_u16 connection_count;
} LoomGeneratedWorldRecord;

typedef struct LoomGeneratedWorldRoomRecord {
    LoomGeneratedStableId id;
    LoomGeneratedStableId room;
    loom_u16 position_words[4];
    loom_u16 world;
    loom_u16 order;
} LoomGeneratedWorldRoomRecord;

typedef struct LoomGeneratedWorldConnectionRecord {
    LoomGeneratedStableId id;
    LoomGeneratedStableId source_exit;
    LoomGeneratedStableId target_spawn;
    loom_u16 world;
    loom_u16 order;
} LoomGeneratedWorldConnectionRecord;

extern const LoomGeneratedAssetRecord loom_generated_assets[LOOM_GENERATED_ASSET_STORAGE_COUNT];
extern const LoomGeneratedAssetItemRecord loom_generated_asset_items[LOOM_GENERATED_ASSET_ITEM_STORAGE_COUNT];
extern const LoomGeneratedAssetOutputRecord loom_generated_asset_outputs[LOOM_GENERATED_ASSET_OUTPUT_STORAGE_COUNT];
extern const LoomGeneratedSceneRecord loom_generated_scenes[LOOM_GENERATED_SCENE_STORAGE_COUNT];
extern const LoomGeneratedLayerRecord loom_generated_layers[LOOM_GENERATED_LAYER_STORAGE_COUNT];
extern const LoomGeneratedTileCellRecord loom_generated_tile_cells[LOOM_GENERATED_TILE_CELL_STORAGE_COUNT];
extern const LoomGeneratedCollisionCellRecord loom_generated_collision_cells[LOOM_GENERATED_COLLISION_CELL_STORAGE_COUNT];
extern const LoomGeneratedEntityRecord loom_generated_entities[LOOM_GENERATED_ENTITY_STORAGE_COUNT];
extern const LoomGeneratedComponentRecord loom_generated_components[LOOM_GENERATED_COMPONENT_STORAGE_COUNT];
extern const LoomGeneratedWorldRecord loom_generated_worlds[LOOM_GENERATED_WORLD_STORAGE_COUNT];
extern const LoomGeneratedWorldRoomRecord loom_generated_world_rooms[LOOM_GENERATED_WORLD_ROOM_STORAGE_COUNT];
extern const LoomGeneratedWorldConnectionRecord loom_generated_world_connections[LOOM_GENERATED_WORLD_CONNECTION_STORAGE_COUNT];

#endif
